import subprocess
import tempfile
from datetime import date
from pathlib import Path
from unittest.mock import patch

from django.test import TestCase, override_settings
from django.urls import reverse

from examc_app.tests.helpers.models import create_mock_exam, create_mock_user
from examc_app.utils.amc_functions import ensure_amc_project
from examc_app.utils.preparation_functions import compile_exam_preview


class ExamTexTestCase(TestCase):
    """exam.tex is generated by the preparation module, it is not a base file copied into the AMC project."""

    def setUp(self):
        projects_root = tempfile.TemporaryDirectory()
        self.addCleanup(projects_root.cleanup)
        override = override_settings(AMC_PROJECTS_ROOT=projects_root.name)
        override.enable()
        self.addCleanup(override.disable)

        self.exam = create_mock_exam()
        self.exam.date = date(2026, 1, 15)
        self.exam.save()

    def exam_tex(self) -> Path:
        return Path(ensure_amc_project(self.exam)) / "exam.tex"

    def test_project_has_no_exam_tex_before_the_content_is_saved(self):
        self.assertFalse(self.exam_tex().exists())

    def test_saving_the_first_page_generates_exam_tex(self):
        user = create_mock_user()
        user.is_superuser = True
        user.save()
        self.client.force_login(user)

        response = self.client.post(
            reverse("prep_first_page_panel", kwargs={"exam_pk": self.exam.pk}), {"first_page_text": "Welcome"}
        )

        self.assertEqual(response.status_code, 200)
        self.assertTrue(self.exam_tex().exists())
        self.assertTrue((self.exam_tex().parent / "first_page.tex").exists())

    def test_preview_generates_the_missing_exam_tex(self):
        failed_latex = subprocess.CompletedProcess(args=[], returncode=1, stdout="LaTeX failed", stderr="")

        with patch("examc_app.utils.preparation_functions.subprocess.run", return_value=failed_latex):
            result = compile_exam_preview(self.exam, job_id=1)

        self.assertTrue(self.exam_tex().exists())
        # The compilation itself is mocked: the error is the one of LaTeX, not the one of the missing file
        self.assertEqual(result["error"], "LaTeX failed")
